INSERT INTO character_data (account_id, name, gender, race, class, level, deity, birthday, last_login, zone_id, x, y, z, heading, str, sta, cha, dex, `int`, agi, wis, points, cur_hp, hunger_level, thirst_level) VALUES (86, 'Claudewright', 0, 1, 12, 1, 396, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 202, -285, -148, -159, 0, 75, 75, 75, 75, 75, 75, 75, 30, 1000, 6000, 6000);
INSERT INTO character_bind (id, slot, zone_id, instance_id, x, y, z, heading) SELECT character_data.id, slots.slot, 202, 0, -285, -148, -159, 0 FROM character_data JOIN (SELECT 0 AS slot UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) AS slots WHERE character_data.name = 'Claudewright';
INSERT INTO character_skills (id, skill_id, value) SELECT character_data.id, skills.skill_id, skills.value FROM character_data JOIN (SELECT 50 AS skill_id, 100 AS value UNION ALL SELECT 40, 200) AS skills WHERE character_data.name = 'Claudewright';
INSERT INTO character_languages (id, lang_id, value) SELECT id, 0, 100 FROM character_data WHERE name = 'Claudewright';
